def score_text(txt, min_words=150):
    "Score markdown `txt`, skipping rule evaluation below `min_words` scored words"
    if min_words < 0: raise ValueError('min_words must be non-negative')
    words = scored_words(segment(txt))
    return Result(txt, run_rules(txt) if words >= min_words else [], words, min_words=min_words)

def _parse(raw, suffix):
    "Markdown in `raw`, the text of a file with `suffix`, and the `Result` attributes that locate findings in that file"
    cells,src,line0 = None,None,0
    if suffix == '.ipynb':
        cells, off = [], 0
        for c in dict2nb(json.loads(raw)).cells:
            if c.cell_type != 'markdown': continue
            cells.append((off, c))
            off += len(c.source) + 2
        txt = '\n\n'.join(c.source for _,c in cells)
    elif suffix == '.py':
        src = raw
        mod = ast.parse(src)
        txt = ast.get_docstring(mod, clean=False) or ''
        if txt: line0 = mod.body[0].lineno - 1
    else: txt = raw
    return txt, dict(cells=cells, src=src, line0=line0)

def _read_file(p):
    "File `p`'s Markdown, and the `Result` attributes that locate findings in the file"
    p = Path(p).expanduser()
    txt,loc = _parse(p.read_text(), p.suffix.lower())
    return txt, dict(path=p, **loc)

def _score_file(p, scorer, min_words):
    "Score file `p`'s Markdown with `scorer`, locating findings in the file"
    txt,loc = _read_file(p)
    res = scorer(txt, min_words=min_words)
    vars(res).update(loc)
    return res

def score_path(p, min_words=150):
    "Score a Markdown file, an `.ipynb` file's Markdown cells, or a `.py` file's module docstring, with exhash addresses"
    return _score_file(p, score_text, min_words)

# %% ../nbs/05_score.ipynb #0e3b855b
def score_many(txts, n_workers=8, min_words=150):
    "Score texts in parallel threads, applying `min_words` to each text"
    return parallel(score_text, txts, n_workers=n_workers, threadpool=True, min_words=min_words)

# %% ../nbs/05_score.ipynb #5339228d
def _doc_paths(paths):
    "Files to score in `paths`: each file as given, then each directory's Markdown, Quarto, notebook and `.py` files"
    res = []
    for p in listify(paths):
        p = Path(p).expanduser()
        res += sorted(fd(root=p, ext=['md', 'qmd', 'ipynb', 'py'])) if p.is_dir() else [p]
    return res

def score_paths(paths, n_workers=8, min_words=150):
    "Score files and directories in parallel threads, one `Result` per file"
    return parallel(score_path, _doc_paths(paths), n_workers=n_workers, threadpool=True, min_words=min_words)

