def rev_text(p, rev='HEAD'):
    "Text of file `p` at git revision `rev`; None if `p` is outside git or `rev` lacks it"
    p = Path(p).expanduser().resolve()
    g = Git(p.parent)
    top = g.top()
    if top is None: return None
    r = g.show(f'{rev}:{p.relative_to(top).as_posix()}', mute_errors=True)
    return None if r is None else r.stdout

def _dens(r): return 'n/a' if r.too_short else r.density

class Change:
    "Prose words and density of one file at a git revision (`old`, None if absent there) and now (`new`)"
    def __init__(self, path, old, new): store_attr()
    def __repr__(self):
        o,n = self.old,self.new
        if o is None: return f'{self.path}: {n.words} words, density {_dens(n)}; no earlier version'
        pct = f' ({100*(n.words-o.words)/o.words:+.0f}%)' if o.words else ''
        return f'{self.path}: {o.words} → {n.words} words{pct}, density {_dens(o)} → {_dens(n)}'

class Changes(list):
    "`Change`s, one per line, then word totals over the files that have an earlier version"
    def __repr__(self):
        both = [c for c in self if c.old]
        o,n = sum(c.old.words for c in both),sum(c.new.words for c in both)
        pct = f' ({100*(n-o)/o:+.0f}%)' if o else ''
        return '\n'.join([*map(repr, self), f'total: {o} → {n} words{pct}'])

def _score_rev(p, rev, min_words):
    "`Result` for file `p` at git revision `rev`; None if `rev_text` finds no text"
    raw = rev_text(p, rev)
    if raw is None: return None
    p = Path(p).expanduser()
    txt,loc = _parse(raw, p.suffix.lower())
    res = score_text(txt, min_words=min_words)
    vars(res).update(loc, path=p)
    return res

def score_vs(paths, rev='HEAD', n_workers=8, min_words=150):
    "Score files and directories now and at git revision `rev`, one `Change` per file"
    def _vs(p): return Change(p, _score_rev(p, rev, min_words), score_path(p, min_words))
    return Changes(parallel(_vs, _doc_paths(paths), n_workers=n_workers, threadpool=True))
